INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Konsistenz im Design nur eine Stilfrage?', 2, '[{"text": "Nein", "correct": true, "because": "Sie verbessert Benutzbarkeit"}, {"text": "Ja", "correct": false, "because": "Funktion steht im Vordergrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem einheitlichen Layout?', 3, '[{"text": "Klarheit", "correct": true, "because": "Nutzer finden sich leichter zurecht"}, {"text": "Maximale Vielfalt", "correct": false, "because": "Kann Verwirrung stiften"}, {"text": "Technische Effizienz", "correct": false, "because": "Nicht primär relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien fördern Einfachheit im Design?', 5, '[{"text": "Reduktion auf Wesentliches", "correct": true, "because": "Vermeidet Überladung"}, {"text": "Konsistentes Layout", "correct": true, "because": "Erhöht Verständlichkeit"}, {"text": "Viele Farben", "correct": false, "because": "Kann ablenken"}, {"text": "Komplexe Animationen", "correct": false, "because": "Erschwert Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Einfachheit erhöht Benutzbarkeit. b) Konsistenz ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Konsistenz ist essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem einfachen Design?', 4, '[{"text": "Nutzerfreundlichkeit", "correct": false, "because": "Kernziel der Einfachheit"}, {"text": "Klarheit", "correct": false, "because": "Wichtig für Verständnis"}, {"text": "Überflüssige Elemente", "correct": true, "because": "Werden reduziert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Konsistenz die Lernkurve verkürzt?', 2, '[{"text": "Ja", "correct": true, "because": "Wiederholung erleichtert Nutzung"}, {"text": "Nein", "correct": false, "because": "Einheitlichkeit hilft Nutzern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element sorgt für Konsistenz in einer App?', 3, '[{"text": "Einheitliche Schaltflächen", "correct": true, "because": "Erkennbarkeit steigt"}, {"text": "Zufällige Farben", "correct": false, "because": "Verwirrt Nutzer"}, {"text": "Unterschiedliche Layouts", "correct": false, "because": "Bricht Konsistenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze fördern Klarheit im Design?', 5, '[{"text": "Wenige Funktionen", "correct": true, "because": "Reduziert Komplexität"}, {"text": "Einheitliches Design", "correct": true, "because": "Vermeidet Verwirrung"}, {"text": "Viele Optionen", "correct": false, "because": "Überfordert Nutzer"}, {"text": " Versteckte Menüs", "correct": false, "because": "Erschwert Navigation"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Einfachheit spart Zeit. b) Konsistenz ist nur für Designer wichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Konsistenz hilft allen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein klares Layout?', 4, '[{"text": "Strukturierte Anordnung", "correct": false, "because": "Fördert Übersicht"}, {"text": "Wenige Elemente", "correct": false, "because": "Unterstützt Klarheit"}, {"text": "Komplexe Grafiken", "correct": true, "because": "Lenken ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Einfachheit immer subjektiv?', 2, '[{"text": "Nein", "correct": true, "because": "Objektive Prinzipien gelten"}, {"text": "Ja", "correct": false, "because": "Nutzerfreundlichkeit ist messbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Designs fördern Benutzbarkeit?', 4, '[{"text": "Einheitliche Navigation", "correct": true, "because": "Erleichtert Orientierung"}, {"text": "Minimalistisches Layout", "correct": true, "because": "Fokus auf Wichtiges"}, {"text": "Viele Untermenüs", "correct": false, "because": "Verwirrt Nutzer"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Konsistenz die Entwicklung erschwert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sie vereinfacht Wartung"}, {"text": "Ja", "correct": false, "because": "Konsistenz spart Zeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für ein einfaches Interface?', 3, '[{"text": "Klarer Fokus", "correct": true, "because": "Nutzer bleiben orientiert"}, {"text": "Viele Features", "correct": false, "because": "Überfordert"}, {"text": "Dekorative Elemente", "correct": false, "because": "Lenken ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Einheitliches Layout hilft Nutzern. b) Reduktion ist nur für kleine Apps.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Reduktion ist universell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente fördern ein konsistentes Design?', 5, '[{"text": "Wiederholte Muster", "correct": true, "because": "Erkennbarkeit steigt"}, {"text": "Einheitliche Farben", "correct": true, "because": "Stärkt Identität"}, {"text": "Zufällige Platzierung", "correct": false, "because": "Bricht Konsistenz"}, {"text": "Viele Schriftarten", "correct": false, "because": "Verwirrt Nutzer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem einfachen Design unwichtig?', 3, '[{"text": "Benutzerführung", "correct": false, "because": "Kern der Einfachheit"}, {"text": "Konsistenz", "correct": false, "because": "Fördert Verständnis"}, {"text": "Visuelle Effekte", "correct": true, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit der Reduktion? Ist sie immer nötig?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Kontext"}, {"text": "Ja", "correct": false, "because": "Flexibilität ist wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Konsistenz auch Entwicklern hilft?', 2, '[{"text": "Ja", "correct": true, "because": "Erleichtert Code-Wartung"}, {"text": "Nein", "correct": false, "because": "Vorteil für alle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip wähle ich für ein übersichtliches Dashboard?', 4, '[{"text": "Einheitliche Anordnung", "correct": true, "because": "Fördert Lesbarkeit"}, {"text": "Viele Widgets", "correct": false, "because": "Überfordert"}, {"text": "Zufällige Farben", "correct": false, "because": "Stört Konsistenz"}]');
